CREATE OR REPLACE FUNCTION pooltune_trial_b9e3cafb4229236b5069b00f.pooltune_memory_sum()
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET work_mem TO '4MB'
 SET max_parallel_workers_per_gather TO '0'
 SET jit TO 'off'
AS $function$DECLARE slot integer; admitted boolean := false; answer bigint;
BEGIN
 FOR slot IN 1..3 LOOP
  IF pg_catalog.pg_try_advisory_xact_lock(27026,slot) THEN admitted := true; EXIT; END IF;
 END LOOP;
 IF NOT admitted THEN RAISE EXCEPTION 'memory concurrency limit' USING ERRCODE='53300'; END IF;
 SELECT sum(lookup) FROM (SELECT lookup FROM ONLY "pooltune_trial_b9e3cafb4229236b5069b00f"."candidate" ORDER BY padding,lookup OFFSET 0) AS sorted INTO answer;
 RETURN answer;
END$function$

